import assert from 'node:assert/strict';
import fs from 'node:fs';
const read=(path:string)=>fs.readFileSync(path,'utf8');
const move=read('app/move/page.tsx');
const form=read('app/components/DriverRiderInterestForm.tsx');
const adminApi=read('app/api/admin/move/quotes/route.ts');
const inbox=read('app/admin/move/quotes/page.tsx');
const migration=read('supabase/migrations/20261123020000_move_quote_admin_followup.sql');
const customerApi=read('app/api/move/quotes/route.ts');

assert(move.includes('Earn?')===false);
assert(move.includes('/earn?role=PASSENGER_FLEET_OPERATOR#join'), 'Move must allow direct cab/bus fleet registration');
assert(move.includes('/earn?role=LOGISTICS_FLEET_OPERATOR#join'), 'Move must allow direct goods fleet registration');
assert(move.includes('No guaranteed bookings') || move.includes('No guaranteed bookings or operator subscription'), 'No false operator income promise');
for(const role of ['PASSENGER_FLEET_OPERATOR','LOGISTICS_FLEET_OPERATOR']) assert(form.includes(role), 'Missing permitted operator role');
assert(form.includes('roles.some(([value]) => value === requestedRole)'), 'Campaign role must be whitelisted');
for(const town of ['Jagtial','Dharmaram','Korutla','Metpally','Dharmapuri']) assert(form.includes(town), 'District role selection missing '+town);
assert(form.includes('does not sign a transport contract'), 'Operator interest must remain unapproved');
assert(migration.includes('admin_notes') && migration.includes('last_customer_contact_at'));
assert(adminApi.includes(".eq('role','admin')"), 'Private admin authorization must remain enforced');
assert(adminApi.includes("auth.auth.getUser"), 'Admin token must be independently verified');
assert(adminApi.includes('last_customer_contact_at'), 'Contact attempts must persist');
assert(adminApi.includes('notes.length < 20'), 'QUOTED must require written operator evidence');
assert(adminApi.includes('admin_notes: notes'), 'Admin notes must be persisted in private DB');
assert(inbox.includes('Needs attention') && inbox.includes('most urgent first'), 'Inbox must triage older enquiries');
assert(inbox.includes('Private operational notes'), 'Inbox must show private case notes');
assert(inbox.includes('Record customer contact attempt'), 'Inbox must allow follow-up timestamp');
assert(inbox.includes('tel:+91'), 'Mobile admin must be able to contact customer only after consent');
assert(inbox.includes('No quote enquiry can be converted'), 'Inbox must explain regulatory/operator gate');
assert(!customerApi.includes('admin_notes') && !customerApi.includes('last_customer_contact_at'), 'Private case notes must never appear in public API');
assert(read('app/lib/move-readiness.ts').includes('customerBookingAvailable: false'), 'Instant passenger and goods booking must stay hard-disabled');
console.log('ZESHU_MOVE_OPERATOR_TRIAGE_QA=PASS');
